       saving_target_amount, actual_saving_amount, saving_difference_amount, saving_result_message,
       report_status, report_viewed_at, report_closed_at, created_at, updated_at
FROM monthly_spending_analyses
WHERE user_id = #{userId}
  AND analysis_year_month = #{analysisYearMonth}

